import type { Scope, Tessera } from "tessellum";

// ── 1. Public literal values ────────────────────────────────────────────────
// Resolved from the BUILD environment and validated against each tessera's schema
// at bake time. Secret-exposure tesserae can never appear here (P14): bake does not
// resolve them, so there is nothing secret to leak.
const VALUES: Record<string, unknown> = {
  API_BASE_URL: "https://api.example.com",
  RELEASE_CHANNEL: "stable",
};

// ── 2. Handles ──────────────────────────────────────────────────────────────
// Brand + key + identity hash + a phantom `Tessera<V>` type. NO schema — this is
// what keeps zod out of the browser bundle. Client code imports THESE, never the
// real descriptors in config.tesserae.ts.
//
// NOTE: the identity strings below are placeholders. Their rendering is issue #41
// and the hash mechanism is #42 — a real bake cannot emit this line until both land.
export const apiBaseUrl = {
  $tessera: "$tessera",
  key: "API_BASE_URL",
  identity: "tesserav1:xxh128:9f2c77aa4be01d38",
} as Tessera<string>;

export const releaseChannel = {
  $tessera: "$tessera",
  key: "RELEASE_CHANNEL",
  identity: "tesserav1:xxh128:41c09be2d7710a5c",
} as Tessera<"stable" | "beta">;

// ── 3. The inlined shim ─────────────────────────────────────────────────────
// Imports nothing. Carries the structural Scope brand (ADR 0007), so a library
// signature typed `Scope<ConfigOf<typeof widgetTesserae>>` accepts it across
// installs exactly like a pick()-produced scope.

const SCOPE_BRAND = "~tessellum.scope";

// The shim cannot import the library's error classes — it imports nothing at all.
// So it throws a structurally-branded error carrying a stable `code`. This is a
// concrete instance of the gap in issue #45: without a defined contract, every
// emitted shim invents its own error shape and `instanceof` can never work.
function configError(code: string, message: string): Error {
  const error = new Error(message);
  error.name = code;
  Object.assign(error, { code, "~tessellum.error": true });
  return error;
}

export const config: Scope<{
  API_BASE_URL: string;
  RELEASE_CHANNEL: "stable" | "beta";
}> = {
  [SCOPE_BRAND]: true,

  unwrap<V>(t: Tessera<V>): V {
    if (!Object.prototype.hasOwnProperty.call(VALUES, t.key)) {
      throw configError(
        "NotInScopeError",
        `"${t.key}" is not in this baked target. Add it to targets.client in config.manifest.ts and re-run \`tessellum bake\`.`,
      );
    }
    return VALUES[t.key] as V;
  },

  safe<V>(t: Tessera<V>) {
    try {
      return { ok: true as const, value: this.unwrap(t) };
    } catch (error) {
      return { ok: false as const, error: error as Error };
    }
  },
};

// ── 4. Dev-only staleness check ─────────────────────────────────────────────
// In production, staleness is a BUILD-time guarantee: `tessellum bake --check` in CI.
// A runtime check needs the real descriptor, which would re-ship the schema — so the
// dev check reaches it through a DYNAMIC import inside a dead branch. A *static*
// import here would re-ship ~65 KB of zod to production (ADR 0003; issue #20).
if (process.env.NODE_ENV !== "production") {
  void import("./config.tesserae").then((descriptors) => {
    const declared = new Set(
      Object.values(descriptors)
        .flatMap((d) => (Array.isArray(d) ? d : [d]))
        .map((d) => (d as { key?: string }).key)
        .filter((key): key is string => typeof key === "string"),
    );
    // A real bake compares identity hashes here. Until #41/#42 land, presence is
    // all this can honestly check — which is itself a finding, not a shortcut.
    for (const handle of [apiBaseUrl, releaseChannel]) {
      if (!declared.has(handle.key)) {
        console.warn(
          `[tessellum] StaleBakeError: "${handle.key}" is baked but no longer declared. Re-run \`tessellum bake\`.`,
        );
      }
    }
  });
}
